#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

BASIC_COUNT=1
SKILL_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
source "$SKILL_DIR/scripts/setup-input.sh"
export PATH="$HOME/.local/bin:/opt/homebrew/bin:/usr/local/bin:$PATH"
WINDOWS=0
case "$(uname -s)" in MINGW*|MSYS*|CYGWIN*) WINDOWS=1 ;; esac
MODE=""
GROUP_LIBRARY=0
ADVANCED=0
export PAPER2ZOTERO_AGENT="${PAPER2ZOTERO_AGENT:-auto}"
while (( $# )); do
  case "$1" in
    --help)
      echo 'Usage: bash install/setup.sh [--dependencies-only | --check] [--advanced] [--group] [--agent auto|codex|claude-code|pi|all]'
      exit 0 ;;
    --group) GROUP_LIBRARY=1 ;;
    --advanced) ADVANCED=1 ;;
    --agent)
      [[ $# -ge 2 ]] || { echo '--agent needs a value' >&2; exit 2; }
      PAPER2ZOTERO_AGENT="$2"; shift ;;
    --dependencies-only|--check)
      [[ -z "$MODE" ]] || { echo 'Choose one setup mode' >&2; exit 2; }
      MODE="$1" ;;
    *) echo 'Unknown option; use --help' >&2; exit 2 ;;
  esac
  shift
done
case "$PAPER2ZOTERO_AGENT" in auto|codex|claude-code|pi|all) ;; *) echo 'Unknown agent; use --help' >&2; exit 2;; esac
if [[ "$MODE" == --dependencies-only ]]; then
  exec bash "$SKILL_DIR/scripts/bootstrap.sh" --dependencies-only
fi
if [[ "$MODE" == --check ]]; then
  if [[ "$GROUP_LIBRARY" == 1 ]]; then
    exec bash "$SKILL_DIR/scripts/bootstrap.sh" --check --group
  fi
  exec bash "$SKILL_DIR/scripts/bootstrap.sh" --check
fi
if [[ "$ADVANCED" == 1 ]]; then
  TOTAL_STAGES=2
  [[ "$GROUP_LIBRARY" == 1 ]] && TOTAL_STAGES=3
else
  TOTAL_STAGES=$((3 + BASIC_COUNT))
  [[ "$GROUP_LIBRARY" == 1 ]] && TOTAL_STAGES=$((TOTAL_STAGES + 1))
fi
# The library remains verbatim. Setup-specific behavior lives below STAGES.
umask 077
ENV_FILE="$HOME/.config/literature-to-zotero/env"
[[ -t 0 ]] || { echo '请在交互终端运行 setup；Agent 可先用 --dependencies-only。'; exit 2; }
connect_account() {
  local service="$1" value="$2"
  local args=(--connect "$service")
  if [[ "$service" == zotero && "$GROUP_LIBRARY" == 1 ]]; then
    args+=(--group --group-id "${ZOTERO_LIBRARY_ID:-}")
  fi
  printf '%s' "$value" | "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" "${args[@]}"
}

shared_guide() {
  "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" --guide "$1"
}

# Preserve the existing platform installers; acceptance and saving are shared
# with the GUI through configure.py --extra after the user finishes login.
prepare_extra() {
  if [[ "$1" == desktop ]]; then
    if [[ "$(uname -s)" == Darwin ]]; then
      if [[ ! -d /Applications/Zotero.app && ! -d "$HOME/Applications/Zotero.app" ]]; then
        if command -v brew >/dev/null 2>&1; then brew install --cask zotero || warn '请按网页说明安装 Zotero。'; else open_setup_url 'https://www.zotero.org/download'; fi
      fi
      open -a Zotero || true
    elif [[ "$WINDOWS" == 1 ]]; then
      powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$(cygpath -w "$SKILL_DIR/scripts/windows-zotero.ps1")" || warn '请从开始菜单打开 Zotero，或重跑安装。'
    else
      open_setup_url 'https://www.zotero.org/download'
    fi
  else
    local kimi_bin installer
    kimi_bin="$(command -v kimi-webbridge || true)"
    kimi_bin="${kimi_bin:-$HOME/.kimi-webbridge/bin/kimi-webbridge}"
    if [[ "$WINDOWS" == 1 ]]; then
      if [[ -x "$HOME/.kimi-webbridge/bin/kimi-webbridge.exe" ]]; then kimi_bin="$HOME/.kimi-webbridge/bin/kimi-webbridge.exe"; fi
    elif [[ ! -x "$kimi_bin" ]]; then
      installer="$(mktemp)"
      if curl -fsSL https://cdn.kimi.com/webbridge/install.sh -o "$installer"; then bash "$installer" || warn '连接服务安装未完成，请按网页说明继续。'; fi
      rm -f "$installer"
    fi
    if [[ -x "$kimi_bin" ]]; then "$kimi_bin" start || warn '连接服务尚未启动。'; fi
    open_setup_url 'https://www.kimi.com/products/kimi-webbridge'
  fi
  pause '按网页说明完成安装、登录或扩展授权后，回车检查'
}

open_setup_url() {
  if [[ "$WINDOWS" == 1 && -n "${PYTHON_BIN:-}" ]]; then
    note "打开网页：$1"
    "$PYTHON_BIN" -c 'import os, sys; os.startfile(sys.argv[1])' "$1" 2>/dev/null || warn "浏览器未能打开，请复制这个网址到浏览器：$1"
  else
    open_url "$1"
  fi
}

_clear
printf '\n%s%s  把论文和阅读笔记放进 Zotero%s\n\n' "$BOLD" "$BLUE" "$RESET"
say '工具由安装器准备。先打开本机 Zotero。可选授权码在后面的步骤。'
say '基础配置检查三件事。scansci-pdf 1.19.0 能导入，全文转换有一条可用通路，本机 Zotero 能写入。'
say 'scansci 下载 PDF 时默认包含灰色来源。只要合法来源，设置 SCANSCI_LEGAL_ONLY=1，或在处理时加 --legal-only。'
note 'Ctrl-C 可退出，已保存内容会保留。'
if [[ "$ADVANCED" == 1 ]]; then note '已打开更多设置：检索来源、电脑同步、浏览器全文。'; fi
pause '按回车开始'

stage "准备工具和 AI 助手"
bash "$SKILL_DIR/scripts/bootstrap.sh" --runtime-only
IFS= read -r PYTHON_BIN < "$HOME/.config/literature-to-zotero/python-path"
if [[ "$WINDOWS" == 1 ]]; then PYTHON_BIN="$(cygpath -u "$PYTHON_BIN")"; fi
export PYTHON_BIN
if ! "$PYTHON_BIN" "$SKILL_DIR/scripts/install.py" --detect; then
  say '你要在哪个 AI 助手中使用？1 = Codex，2 = Claude Code，3 = Pi'
  while true; do
    printf '  输入 1、2 或 3：'
    IFS= read -r AGENT_CHOICE || { note '配置已暂停，重跑向导可继续。'; exit 130; }
    case "$AGENT_CHOICE" in
      1) PAPER2ZOTERO_AGENT=codex; break ;;
      2) PAPER2ZOTERO_AGENT=claude-code; break ;;
      3) PAPER2ZOTERO_AGENT=pi; break ;;
      *) warn '请选择一个助手。' ;;
    esac
  done
fi
bash "$SKILL_DIR/scripts/install-skill.sh"
if [[ "$ADVANCED" == 0 ]]; then
pause '准备完成，回车检查本机 Zotero'

stage "Zotero Desktop · 本机附件"
say '基础配置要本机 Zotero 能写入。打开应用后，这一步检查本地接口。'
say '授权框选「始终允许」。附件同步不在这一步。'
prepare_extra desktop
if ! "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" --extra desktop; then
  warn '尚未启用，已保存的配置保留；可在准备完成后回来检查。'
fi
pause '按回车继续'
fi

if [[ "$GROUP_LIBRARY" == 1 ]]; then
stage "连接 Zotero Web API"
say '群组文库需要 Web API 授权码。个人文库写入走本机 Desktop，不在这一步手填个人文库 ID。'
open_setup_url 'https://www.zotero.org/settings/keys'
step '1. 登录 Zotero。还没有账号，可先在网页上注册。'
step '2. 新建授权码，勾选 Allow library access、Allow notes access、Allow write access。'
step '3. 允许目标群组的读取和写入。'
step '4. 复制 Key，粘贴到下方。'
while true; do
  ask_authorization ZOTERO_API_KEY '粘贴 Zotero 授权码（没有则回车跳过）：'
  if [[ -n "$ZOTERO_API_KEY" ]]; then
    ask ZOTERO_LIBRARY_ID '填写要保存到的群组文库 ID（数字；回车稍后配置）：'
    if connect_account zotero "$ZOTERO_API_KEY"; then
      unset ZOTERO_API_KEY ZOTERO_LIBRARY_ID ZOTERO_LIBRARY_TYPE
    else
      unset ZOTERO_API_KEY ZOTERO_LIBRARY_ID ZOTERO_LIBRARY_TYPE
      warn '连接未完成；原有账号已保留，无需手动查找个人文库 ID。'
      if retry_connection; then continue; fi
    fi
  else
    note '已跳过 Zotero Web API；群组写入需稍后补齐。'
  fi
  break
done
pause 'Web API 这一步结束，按回车继续'
fi

if [[ "$ADVANCED" == 0 ]]; then
stage "检查结果，开始使用"
check_args=(--check)
[[ "$GROUP_LIBRARY" == 1 ]] && check_args+=(--group)
if "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" "${check_args[@]}"; then
  pause '检查通过，回车查看结果'
  _clear
  say '✓ 配置完成。回到你的 AI 助手，试着说：'
  say '“帮我找近三年 AI 心理健康干预的研究，先给我一份候选清单。”'
  note '如果暂时找不到技能，新开一个助手会话再试。'
  note '接下来直接展示更多配置；不需要的项目可跳过。'
else
  warn '部分配置尚未完成；已填写内容保留，重跑 setup 即可继续。'
  SETUP_RESULT=1
fi
fi

extra_names() {
  local py="${PYTHON_BIN:-}"
  if [[ -n "$py" && -x "$py" ]]; then
    "$py" -c 'import sys; sys.path.insert(0, sys.argv[1]); from setup_connection import wizard_extras
print("\n".join(wizard_extras()))' "$SKILL_DIR/scripts"
    return
  fi
  printf '%s\n' zotero mineru kimi semantic_scholar crossref unpaywall
}

stage "更多配置（可选）"
say '可选项目已依次展开。留空或跳过会保留已有配置。'
services=()
if names="$(extra_names)"; then
  while IFS= read -r name; do
    name=${name%$'\r'}
    [[ -n "$name" ]] && services+=("$name")
  done <<<"$names"
else
  while IFS= read -r name; do
    services+=("$name")
  done <<'FALLBACK'
zotero
mineru
kimi
semantic_scholar
crossref
unpaywall
FALLBACK
fi
for service in "${services[@]}"; do
  shared_guide "$service"
  if [[ "$service" == kimi || "$service" == desktop ]]; then
    if confirm '现在准备并连接这项功能'; then
      prepare_extra "$service"
      if ! "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" --extra "$service"; then
        warn '尚未启用，已保存的配置保留；可在准备完成后回来检查。'
      fi
    fi
  else
    case "$service" in
      zotero) setting=ZOTERO_API_KEY; ask_authorization "$setting" '粘贴 Zotero 授权码（可留空）：' ;;
      openalex) setting=OPENALEX_API_KEY; ask_authorization "$setting" '粘贴 OpenAlex 授权码（可留空）：' ;;
      mineru) setting=MINERU_TOKEN; ask_authorization "$setting" '粘贴 MinerU Token（可留空）：' ;;
      semantic_scholar) setting=SEMANTIC_SCHOLAR_API_KEY; ask_authorization "$setting" 'Semantic Scholar API Key（可留空，申请未完成可稍后回来）：' ;;
      crossref) setting=CROSSREF_MAILTO; ask "$setting" 'Crossref 联系邮箱（可留空）：' ;;
      unpaywall) setting=UNPAYWALL_EMAIL; ask "$setting" 'Unpaywall 联系邮箱（可留空）：' ;;
    esac
    value="${!setting}"
    if [[ -n "$value" ]] && ! printf '%s' "$value" | "$PYTHON_BIN" "$SKILL_DIR/scripts/configure.py" --extra "$service"; then
      warn '本项未保存，原有设置保留；请按提示修正后重试。'
    fi
    unset "$setting" value
  fi
  printf '\n'
done
note '更多配置可随时重新打开：bash install/setup.sh --advanced。无需重填基础账号。'

say '总结提示词可以换成你更熟悉的版本，保留默认也可以直接使用。'
if confirm '想换用自己的总结提示词？查看需要修改的文件位置'; then
  say '需要修改的文件：'
  "$PYTHON_BIN" - "$SKILL_DIR/scripts" "$PAPER2ZOTERO_AGENT" <<'PY'
import sys
from pathlib import Path
sys.path.insert(0, sys.argv[1])
from agent_installation import installed_paths
paths = dict.fromkeys(str((Path(root) / 'references' / 'paper-summary.md').resolve())
                      for root in installed_paths(agent=sys.argv[2]))
for path in paths:
    print('  ' + path)
if not paths:
    print('  在当前助手实际加载的 paper-to-zotero 目录中，找到 references/paper-summary.md。')
PY
  step '用文本编辑器打开该 Markdown 文件，将开头的阅读分析要求换成自己的提示词。'
  step '保留“## Save and continue”及之后的保存、续跑说明；无需修改账号配置。'
  note '保存后在新文献任务中使用；已有笔记不会自动重写。托管更新会保留自定义提示词，也建议自行保存副本。'
  note '这里只提供修改位置，不打开编辑器、不修改文件。'
fi

exit "${SETUP_RESULT:-0}"
